import{_ as o,C as s,o as a,c as i,a2 as e,E as n}from"./chunks/framework.BSaF8iZ6.js";const m=JSON.parse('{"title":"Seller Attributes","description":"","frontmatter":{},"headers":[],"relativePath":"sellers/seller-attributes.md","filePath":"sellers/seller-attributes.md","lastUpdated":1789411447000}'),l={name:"sellers/seller-attributes.md"};function g(d,t,u,h,p,c){const r=s("ImagePopup");return a(),i("div",null,[t[0]||(t[0]=e('<h1 id="seller-attributes" tabindex="-1">Seller Attributes <a class="header-anchor" href="#seller-attributes" aria-label="Permalink to &quot;Seller Attributes&quot;">​</a></h1><div class="page-roles"><span class="role role--admin">Admin</span></div><p>Seller attributes are the fields that make up a seller&#39;s details: what they fill in when they sign up, what they see on their profile, and what customers see on their shop page. The marketplace comes with the fields most stores need, and you can add your own, such as a tax number.</p><h2 id="the-attributes-list" tabindex="-1">The attributes list <a class="header-anchor" href="#the-attributes-list" aria-label="Permalink to &quot;The attributes list&quot;">​</a></h2><p>Go to <strong>Marketplace &gt;&gt; Sellers &gt;&gt; Seller Attributes</strong>.</p>',5)),n(r,{src:"/images/seller-attributes/seller-attributes.png",alt:"The Seller Attributes list"}),t[1]||(t[1]=e('<p>The list shows each attribute&#39;s <strong>Code</strong>, <strong>Name</strong> and <strong>Type</strong>, and whether it is required, unique, or saved per language or channel. Use the row icons to edit or delete an attribute. The built-in attributes can&#39;t be deleted.</p><h2 id="create-an-attribute" tabindex="-1">Create an attribute <a class="header-anchor" href="#create-an-attribute" aria-label="Permalink to &quot;Create an attribute&quot;">​</a></h2><ol><li>Go to <strong>Marketplace &gt;&gt; Sellers &gt;&gt; Seller Attributes</strong>.</li><li>Click <strong>Create Seller Attribute</strong>.</li><li>In <strong>Label</strong>, enter the <strong>Admin</strong> name, and the name sellers and customers see in each language.</li><li>In <strong>General</strong>, enter an <strong>Attribute Code</strong> and choose the <strong>Attribute Type</strong>.</li><li>Set the options in <strong>Validations</strong> and <strong>Configuration</strong>.</li><li>Click <strong>Save Seller Attribute</strong>.</li></ol>',3)),n(r,{src:"/images/seller-attributes/attribute-create.png",alt:"The Add Seller Attribute form"}),t[2]||(t[2]=e('<p>A new attribute doesn&#39;t appear anywhere until you place it in a group on the <strong>Mapping</strong> screen. See <a href="#place-attributes-on-the-form">Place attributes on the form</a>.</p><h3 id="attribute-types" tabindex="-1">Attribute types <a class="header-anchor" href="#attribute-types" aria-label="Permalink to &quot;Attribute types&quot;">​</a></h3><p>The <strong>Attribute Type</strong> can be <strong>Text</strong>, <strong>Textarea</strong>, <strong>Price</strong>, <strong>Boolean</strong>, <strong>Checkbox</strong>, <strong>Select</strong>, <strong>Multiselect</strong>, <strong>Date</strong>, <strong>Datetime</strong>, <strong>Image</strong> or <strong>File</strong>. Some fields depend on the type:</p><ul><li><strong>Enable Editor</strong> gives a <strong>Textarea</strong> a rich-text editor.</li><li><strong>Default Value</strong> sets the starting value of a <strong>Boolean</strong>.</li><li><strong>Options</strong> appears for <strong>Select</strong>, <strong>Multiselect</strong> and <strong>Checkbox</strong>. Click <strong>Add Row</strong> to add a choice with its name in each language, and drag rows to change their order. For a <strong>Select</strong>, <strong>Create default empty option</strong> adds a blank first choice.</li><li><strong>Input Validation</strong> appears for <strong>Text</strong>: <strong>Numeric</strong>, <strong>Email</strong>, <strong>Decimal</strong>, <strong>URL</strong> or <strong>Regex</strong>. With <strong>Regex</strong>, enter the expression in the <strong>Regex</strong> field.</li></ul><h3 id="validations-and-configuration" tabindex="-1">Validations and configuration <a class="header-anchor" href="#validations-and-configuration" aria-label="Permalink to &quot;Validations and configuration&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Is Required</strong></td><td>Sellers must fill in the field.</td></tr><tr><td><strong>Is Unique</strong></td><td>No two sellers can have the same value.</td></tr><tr><td><strong>Value Per Locale</strong></td><td>The seller enters a value for each language.</td></tr><tr><td><strong>Value Per Channel</strong></td><td>The seller enters a value for each channel.</td></tr><tr><td><strong>Visible on Signup Page</strong></td><td>Shows the field on the <strong>Become Seller</strong> form, under <strong>Additional Information</strong>.</td></tr><tr><td><strong>Visible on Profile Page</strong></td><td>Shows the field on the seller&#39;s <strong>Manage Profile</strong> page.</td></tr><tr><td><strong>Visible on Public Page</strong></td><td>Shows the value in the <strong>About</strong> tab of the seller&#39;s shop page.</td></tr></tbody></table><p>Once saved, the code, type and <strong>Input Validation</strong> can&#39;t change, and <strong>Is Unique</strong>, <strong>Value Per Locale</strong> and <strong>Value Per Channel</strong> can&#39;t be turned off. For built-in attributes, <strong>Visible on Profile Page</strong> can&#39;t change, and <strong>Name</strong>, <strong>Email</strong> and <strong>Slug</strong> always stay required and on the sign-up form.</p><h2 id="place-attributes-on-the-form" tabindex="-1">Place attributes on the form <a class="header-anchor" href="#place-attributes-on-the-form" aria-label="Permalink to &quot;Place attributes on the form&quot;">​</a></h2><p>The <strong>Mapping</strong> screen arranges attributes into cards, in two columns. The same layout is used on the admin&#39;s <strong>Edit Seller</strong> page and on the seller&#39;s <strong>Manage Profile</strong> page.</p><ol><li>Go to <strong>Marketplace &gt;&gt; Sellers &gt;&gt; Seller Attributes</strong>.</li><li>Click <strong>Mapping</strong>.</li><li>Drag an attribute from <strong>Unassigned Attributes</strong> into a group under <strong>Main Column</strong> or <strong>Right Side Column</strong>.</li><li>Click <strong>Save Mapping</strong>.</li></ol>',10)),n(r,{src:"/images/seller-attributes/attribute-mapping.png",alt:"The Edit Seller Attribute Mapping screen"}),t[3]||(t[3]=e('<ul><li>To add a card, click <strong>Add Group</strong>, then enter a <strong>Code</strong>, choose the <strong>Column</strong>, and enter the <strong>Admin Name</strong> and the name in each language.</li><li>To rename a group, double-click its name.</li><li>To remove a group, select it and click <strong>Delete Group</strong>. A group that holds built-in attributes can&#39;t be removed until you move them to another group.</li></ul><p>The sign-up form doesn&#39;t use groups. It shows <strong>Name</strong>, <strong>Email</strong>, <strong>Slug</strong> and the password fields first, then every mapped attribute marked <strong>Visible on Signup Page</strong>.</p><h2 id="built-in-attributes" tabindex="-1">Built-in attributes <a class="header-anchor" href="#built-in-attributes" aria-label="Permalink to &quot;Built-in attributes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Card</th><th>Attributes</th><th>Seen by</th></tr></thead><tbody><tr><td>General</td><td>Name, Email, Phone, Slug, Business Name</td><td>Name, Email, Slug and Business Name are on the sign-up form; all are on the profile</td></tr><tr><td>Description</td><td>Business Description</td><td>Profile; the shop page <strong>About</strong> tab</td></tr><tr><td>Policies</td><td>Return Policy, Shipping Policy, Privacy Policy</td><td>Profile; the shop page <strong>About</strong> tab when filled</td></tr><tr><td>Meta Description</td><td>Meta Title, Meta Keywords, Meta Description</td><td>Profile; used for the shop page in search engines</td></tr><tr><td>Address</td><td>Address, City, Country, State, Postcode</td><td>Profile; shown on the shop page</td></tr><tr><td>Social Links</td><td>Facebook, Instagram, YouTube</td><td>Profile; the <strong>Share</strong> menu on the shop page</td></tr><tr><td>Settings</td><td>Minimum Order Amount, Google Analytics ID</td><td>Profile</td></tr><tr><td>Settings</td><td>Commission Enabled, Commission Percentage, Allowed Product Types, Magic AI Enabled, Magic AI Generation Limit</td><td>Admin only, on <strong>Edit Seller</strong></td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>To give another admin access, tick <strong>Marketplace &gt;&gt; Sellers &gt;&gt; Seller Attributes</strong> in their role, with <strong>Create</strong>, <strong>Edit</strong> (which includes <strong>Mapping</strong>) and <strong>Delete</strong> as needed.</p>',6))])}const f=o(l,[["render",g]]);export{m as __pageData,f as default};
